function Hd = FIR
%FIR Returns a discrete-time filter object.

% MATLAB Code
% Generated by MATLAB(R) 9.13 and Signal Processing Toolbox 9.1.
% Generated on: 15-Oct-2025 15:32:55

% FIR Window Lowpass filter designed using the FIR1 function.

% All frequency values are in Hz.
Fs = 8000;  % Sampling Frequency

N    = 127;      % Order
Fc   = 1000;     % Cutoff Frequency
flag = 'scale';  % Sampling Flag
Beta = 10;       % Window Parameter

% Create the window vector for the design algorithm.
win = kaiser(N+1, Beta);

% Calculate the coefficients using the FIR1 function.
b  = fir1(N, Fc/(Fs/2), 'low', win, flag);
Hd = dfilt.dffir(b);


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
figure(1);
F = [0:(Fs/2)/255:Fs/2];
b1 = [b zeros(1,512-length(b))];
bdb = 20*log10(abs(fft(b1)) );  %  + 10^-5
bdb = bdb - max(bdb);
plot(F(2:255),bdb(2:255),'r-');
title('La réponse fréquentielle pour les Coefficients non quantifiés');
grid;
zoom on;
hold on;

%k = input('entrer l''exposant k du format virgule fixe Qk:   ');
k = -1;
bq = 0;
while(max(abs(bq)) <= 32767)
    k = k + 1;
    Qk = 2^k;
    bq = b * Qk;
    bq = round(bq);
end
k = k - 1;
Qk = 2^k;
bq = b * Qk;
bq = round(bq);
bq1 = [bq zeros(1,512-length(bq))];
hdb = 20*log10(abs(fft(bq1)) );
hdb = hdb - max(hdb);
plot(F(2:255),hdb(2:255),'b:');
title('La réponse fréquentielle pour les Coefficients quantifiés par 2^k');
legend('IDEAL', 'QUANTIFIE');
zoom on;
grid on;

h = bq;
disp(['Format k = ' num2str(k) '      |Coefficient maximal| en format Qk = '  num2str(max(abs(h)))]);
reponse = input('Pour la saisie manuelle de k tapez le chiffre 0 sinon tapez 1:  ');
if(reponse == 0) 
    k = input('entrer l''exposant k du format virgule fixe Qk:   ');
    Qk = 2^k;
    bq = b * Qk;
    bq = round(bq);
    h = bq;
    disp(['Format k = ' num2str(k) '      |Coefficient maximal| en format Qk = '  num2str(max(abs(h)))]);
end
reponse = input('Génération des coefficients pour l''assembleur tapez 0 pour C tapez 1:  ');
if reponse == 1 
    fid = fopen('FIR_COEF.h','w');
    fprintf(fid,'#define    N     %d      // Nombre de coefficients du filtre \n\n', N+1);
    fprintf(fid,'#define    Qk     %d      // representation en virgule fixe en Qk \n\n', k);
    fprintf(fid, '// Frequence d''echantillonnage Fs = %d  \n\n', Fs);
    fprintf(fid,'short h[%d',N+1);
    fprintf(fid,']= {');
    for i=1:N
        fprintf(fid,'%d,',h(i));
        if mod(i,16) == 0    fprintf(fid, '\n');
        end
    end
    fprintf(fid,'%d };\n', h(N+1));
else
    fid = fopen('FIR_COEF.asm','w');
    fprintf(fid, 'N    EQU    %d\n\n',N+1);
    for i=0:N    fprintf(fid,'h%d     .word   %d\n',i, h(i+1));
    end;
end
fclose(fid);
% [EOF]
